<?php declare(strict_types=1);require_once __DIR__.'/../config/auth.php';page_require(['ADMIN']);?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Estado del sistema — Franky</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#172033;font-family:Manrope,Arial,sans-serif}.wrap{max-width:980px;margin:auto;padding:82px 14px 32px}h1{margin:0}.sub{color:#64748b;margin:6px 0 18px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.card{background:#fff;border:1px solid #e5eaf0;border-radius:16px;padding:14px}.k{font-size:10px;text-transform:uppercase;color:#64748b;font-weight:900}.v{font-size:20px;font-weight:900;margin-top:4px;word-break:break-word}.counts{margin-top:12px}.row{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #eef2f7}.row:last-child{border:0}.hint{font-size:11px;color:#64748b;margin-top:4px}.diag{margin-top:14px}.diag-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}.diag-head h2{margin:0;font-size:19px}.status{display:inline-flex;align-items:center;gap:7px;padding:7px 10px;border-radius:999px;font-size:12px;font-weight:900}.status.ok{background:#ecfdf3;color:#166534}.status.warn{background:#fff7ed;color:#92400e}.status.err{background:#fff1f2;color:#9f1239}.dot{width:8px;height:8px;border-radius:50%;background:currentColor}.mini-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.mini{background:#f8fafc;border:1px solid #e8edf3;border-radius:12px;padding:11px}.mini b{display:block;font-size:20px}.mini span{font-size:10px;color:#64748b;text-transform:uppercase;font-weight:900}.table{width:100%;border-collapse:collapse}.table th,.table td{text-align:left;padding:9px 8px;border-bottom:1px solid #eef2f7;font-size:12px;vertical-align:top}.table th{font-size:10px;text-transform:uppercase;color:#64748b}.badge{display:inline-block;padding:4px 7px;border-radius:999px;font-size:10px;font-weight:900}.badge.ERROR{background:#fff1f2;color:#9f1239}.badge.WARN{background:#fff7ed;color:#92400e}.empty{color:#64748b;text-align:center;padding:18px}.section-title{font-size:14px;margin:16px 0 8px}.footnote{font-size:11px;color:#64748b;margin-top:10px}@media(max-width:700px){.grid{grid-template-columns:1fr 1fr}.mini-grid{grid-template-columns:1fr 1fr}.wrap{padding-left:12px;padding-right:12px}.table{display:block;overflow-x:auto;white-space:nowrap}}</style></head><body><main class="wrap"><h1>Estado del sistema</h1><div class="sub">Salud técnica, despliegue, respaldo y diagnóstico de Franky.</div><div id="c">Cargando…</div></main><script>
const c=document.getElementById('c'),esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
Promise.all([fetch('/api/estado-sistema.php').then(r=>r.json()),fetch('/api/diagnostico.php',{cache:'no-store'}).then(r=>r.json())]).then(([d,g])=>{if(!d.ok)throw Error(d.error);if(!g.ok)throw Error(g.error);const b=d.backup||{},r=g.resumen||{},errors=Number(r.errores||0),warns=Number(r.avisos||0),cls=errors?'err':(warns?'warn':'ok'),label=errors?'Errores recientes':(warns?'Advertencias':'Todo OK');const recent=(g.recientes||[]),slow=(g.lentas||[]);c.innerHTML=`<div class="grid"><div class="card"><div class="k">Franky</div><div class="v">v${esc(d.version_app)}</div></div><div class="card"><div class="k">Commit</div><div class="v">${esc(d.commit)}</div></div><div class="card"><div class="k">PHP</div><div class="v">${esc(d.php)}</div></div><div class="card"><div class="k">MariaDB</div><div class="v">${esc(d.mariadb)}</div></div><div class="card"><div class="k">Hora servidor</div><div class="v" style="font-size:14px">${esc(d.server_time)}</div></div><div class="card"><div class="k">Respaldo</div><div class="v" style="font-size:14px">${b.visible?(b.ultimo?esc(b.ultimo):'Carpeta visible'):'Protegido'}</div><div class="hint">${b.visible?(b.fecha?esc(b.fecha):'No se encontró respaldo visible'):'El proceso web no puede leer /root/backups, comportamiento seguro.'}</div></div></div><div class="card counts">${Object.entries(d.counts).map(([k,v])=>`<div class="row"><strong>${esc(k)}</strong><span>${v??'—'}</span></div>`).join('')}</div><section class="card diag"><div class="diag-head"><h2>Diagnóstico · últimas 24 h</h2><span class="status ${cls}"><span class="dot"></span>${label}</span></div><div class="mini-grid"><div class="mini"><b>${Number(r.total||0)}</b><span>Eventos</span></div><div class="mini"><b>${errors}</b><span>Errores</span></div><div class="mini"><b>${warns}</b><span>Advertencias</span></div><div class="mini"><b>${Number(r.http_errores||0)}</b><span>HTTP</span></div></div><h3 class="section-title">APIs más lentas</h3>${slow.length?`<table class="table"><thead><tr><th>API</th><th>Promedio</th><th>Máximo</th><th>Muestras</th></tr></thead><tbody>${slow.map(x=>`<tr><td>${esc(x.recurso||'—')}</td><td>${esc(x.promedio_ms)} ms</td><td>${esc(x.max_ms)} ms</td><td>${esc(x.muestras)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Todavía no hay muestras suficientes.</div>'}<h3 class="section-title">Errores y advertencias recientes</h3>${recent.length?`<table class="table"><thead><tr><th>Hora</th><th>Nivel</th><th>Página</th><th>Detalle</th></tr></thead><tbody>${recent.map(x=>`<tr><td>${esc(x.creado_en)}</td><td><span class="badge ${esc(x.nivel)}">${esc(x.nivel)}</span></td><td>${esc(x.pagina||'—')}</td><td>${esc(x.mensaje||x.recurso||'—')}${x.duracion_ms?` · ${esc(x.duracion_ms)} ms`:''}${x.status_http?` · HTTP ${esc(x.status_http)}`:''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Sin errores ni advertencias recientes 🎉</div>'}<div class="footnote">Retención: ${esc(g.retencion_dias)} días · máximo ${esc(g.max_eventos)} eventos. Las URLs se guardan sin parámetros y el sistema no registra contraseñas ni cuerpos de formularios.</div></section>`}).catch(e=>c.textContent=e.message)
</script></body></html>